<?php
declare(strict_types=1);
function camp_init(array &$d):void {foreach(['campaigns','campaign_permissions','campaign_optouts','campaign_reminders','campaign_worker'] as $k)$d[$k]??=[];$d['campaign_settings']??=['enabled'=>false,'daily_limit'=>20,'digest'=>false,'hour'=>8,'follow_days'=>5,'deadline_days'=>7];$d['campaign_settings']['deadline_days']??=7;}
function camp_status_ok(array $l):bool{return in_array($l['status'],['Identificada','Contactada','Sin respuesta'],true)&&$l['confirmed']===0;}
function camp_emails(array $e):array{return array_values(array_unique(array_filter(array_map('strtolower',preg_split('/[,;\s]+/',$e['emails']??'',-1,PREG_SPLIT_NO_EMPTY)),fn($m)=>filter_var($m,FILTER_VALIDATE_EMAIL))));}
function camp_allowed(array $d,string $eid,string $mail):bool{return !isset($d['campaign_optouts'][$mail])&&!empty($d['campaign_permissions'][master_id($eid)][$mail]['allowed'])&&in_array($mail,camp_emails($d['companies'][master_id($eid)]??[]),true);}
function camp_tokens(array $d,array $cfg,string $cid,string $eid,string $mail):array {$e=$d['companies'][master_id($eid)];$l=$d['links'][$cid][$eid];$s=$d['settings'];$base=rtrim($cfg['public_url'],'/');return ['{empresa}'=>$e['name'],'{centro}'=>$s['center'],'{curso}'=>$d['courses'][$cid]['name'],'{grupo}'=>$d['courses'][$cid]['groups'][$l['group']]['name']??'Administración y Gestión','{tutor}'=>$s['tutor'],'{landing}'=>$base.'/index.php?v=landing','{ayudas}'=>$e['kind']==='Empresa'?'Como referencia, la convocatoria '.$s['reference'].' contempló '.number_format((float)$s['rate'],2,',','.').' €/hora efectiva por estudiante para empresas privadas elegibles. No garantiza futuras ayudas. Información: '.$s['boc']:''];}
function camp_default(bool $follow=false):string{return $follow?"Estimado equipo de {empresa}:\n\nRetomamos nuestra invitación a colaborar con {centro} en la formación de {grupo} ({curso}). ¿Desean información adicional o podrían ofrecernos alguna plaza?\n\n{ayudas}\n\nInformación y formulario: {landing}\n\nAtentamente,\n{tutor}":"Estimado equipo de {empresa}:\n\nDesde {centro} invitamos a su entidad a participar en la formación en empresa de {grupo}, curso {curso}. El centro coordina el plan formativo, la documentación y el seguimiento.\n\n{ayudas}\n\nConozca las ventajas y manifieste su interés sin compromiso: {landing}\n\nAtentamente,\n{tutor}";}
function camp_candidates(array $d,string $cid,string $zone,string $kind,string $group):array {$rows=[];$seen=[];$seenCompany=[];foreach($d['links'][$cid]??[] as $eid=>$l){$e=$d['companies'][master_id($eid)];if(!camp_status_ok($l)||($zone!==''&&$zone!==$e['zone'])||($kind!==''&&$kind!==$e['kind'])||($group!==''&&$group!==$l['group']))continue;if(isset($seenCompany[master_id($eid)]))continue;$seenCompany[master_id($eid)]=true;$mail='';foreach(camp_emails($e) as $m)if(camp_allowed($d,$eid,$m)&&!isset($seen[$m])){$mail=$m;$seen[$m]=true;break;}$rows[$eid]=['email'=>$mail,'state'=>$mail?'pending':'manual','due'=>0,'follow_state'=>'none','follow_due'=>0,'attempts'=>0];}return $rows;}
function camp_save_action(string $action,array &$d,array $cfg,string $dir,string $cid,string $eid):string {
 require_admin();$back='?v=campaigns&c='.rawurlencode($cid?:$d['settings']['active']);
 if($action==='camp_settings'){$lim=integer('daily_limit',100);$hour=integer('hour',23);$days=integer('follow_days',30);$deadline=integer('deadline_days',30);if(!$lim||!$days)fail('Indique límites mayores que cero');$d['campaign_settings']=['enabled'=>field('enabled')==='yes','daily_limit'=>$lim,'digest'=>field('digest')==='yes','hour'=>$hour,'follow_days'=>$days,'deadline_days'=>$deadline];audit($d,'Configuración de campañas actualizada');return $back;}
 if($action==='camp_permission'){editable($d,$cid);participation($d,$cid,$eid);$m=email('email');if(!in_array($m,camp_emails($d['companies'][master_id($eid)]),true))fail('Correo no incluido en la ficha');$allow=field('allowed')==='yes';$note=field('evidence',1000);if($allow&&(!$note||isset($d['campaign_optouts'][$m])))fail('Se requiere prueba de autorización y que no exista una baja global');$d['campaign_permissions'][master_id($eid)][$m]=['allowed'=>$allow,'evidence'=>$note,'at'=>date(DATE_ATOM)];audit($d,'Permiso de comunicaciones actualizado',$cid,$eid);return '?v=company&c='.$cid.'&e='.$eid;}
 if($action==='camp_suppress'){ $m=email('email');$d['campaign_optouts'][$m]=date(DATE_ATOM);audit($d,'Baja global de campañas');return $back;}
 editable($d,$cid);
 if($action==='camp_create'){$name=field('name');$subject=field('subject',180);$body=field('body',10000);$follow=field('follow')==='yes';$fb=field('follow_body',10000);if(!$name||!$subject||!$body||($follow&&!$fb))fail('Complete los textos de campaña');$rows=camp_candidates($d,$cid,field('zone'),field('kind'),field('group'));if(!$rows)fail('No hay empresas que coincidan con los filtros');$id=uid();$d['campaigns'][$id]=['course'=>$cid,'name'=>$name,'subject'=>$subject,'body'=>$body,'follow'=>$follow,'follow_body'=>$fb,'follow_days'=>$d['campaign_settings']['follow_days'],'state'=>'draft','created'=>date(DATE_ATOM),'rows'=>$rows];audit($d,'Campaña creada',$cid);return $back.'&campaign='.$id;}
 $id=field('campaign');$p=&$d['campaigns'][$id];if(!$p||$p['course']!==$cid)fail('Campaña inexistente',404);
 if($action==='camp_launch'){if(!in_array($p['state'],['draft','paused'],true)||field('confirm')!=='yes'||!mail_ready($cfg)||!$d['campaign_settings']['enabled']||empty($d['settings']['public']))fail('Confirme el envío, active las campañas, configure Resend y publique la landing');foreach($d['campaigns'] as $otherId=>$other)if($otherId!==$id&&$other['course']===$cid&&$other['state']==='active')fail('Pause la otra campaña activa de este curso');$start=field('start');$when=$start?strtotime($start):time();if($when===false)fail('Fecha no válida');$p['state']='active';foreach($p['rows'] as &$r)if($r['state']==='pending'&&!$r['due'])$r['due']=$when;unset($r);audit($d,'Campaña activada',$cid);}
 elseif($action==='camp_pause'){if($p['state']==='active')$p['state']='paused';}
 elseif($action==='camp_cancel'){$p['state']='cancelled';}
 elseif($action==='camp_tasks'){foreach($p['rows'] as $eid0=>$r0)if($r0['state']==='manual'&&isset($d['links'][$cid][$eid0])&&camp_status_ok($d['links'][$cid][$eid0])&&empty($d['links'][$cid][$eid0]['next']))$d['links'][$cid][$eid0]['next']=date('Y-m-d');audit($d,'Tareas de contacto manual programadas',$cid);}
 elseif($action==='camp_skip'){if(isset($p['rows'][$eid])){$r=&$p['rows'][$eid];if($r['state']==='pending')$r['state']='skipped';if($r['follow_state']==='pending')$r['follow_state']='skipped';}}
 else fail('Acción desconocida');return $back.'&campaign='.$id;
}
function camp_opt_token(array &$d,string $mail):string {$d['campaign_secret']??=bin2hex(random_bytes(32));return hash_hmac('sha256',$mail,$d['campaign_secret']);}
function camp_tick(array &$d,array $cfg,string $dir):void {
 camp_init($d);$s=$d['campaign_settings'];$now=time();$today=date('Y-m-d');$w=&$d['campaign_worker'];$w['last_run']=date(DATE_ATOM);if(($w['day']??'')!==$today){$w['day']=$today;$w['count']=0;}$w['count']??=0;save_db($dir,$d);
 if(!mail_ready($cfg))return;
 if($s['digest']&&(int)date('G')>=$s['hour']&&($w['digest_day']??'')!==$today){$lines=[];$pending=count(array_filter($d['inbox']??[],fn($m)=>$m['state']==='new'));if($pending)$lines[]='Buzón empresarial: '.$pending.' mensajes pendientes de revisión';foreach($d['courses'] as $cid=>$c){if($c['closed'])continue;$limit=date('Y-m-d',strtotime('+'.$s['deadline_days'].' days'));foreach($c['groups'] as $gid=>$g){foreach(['start'=>'Inicio FEOE','end'=>'Fin FEOE'] as $datekey=>$label)if(!empty($g[$datekey])&&$g[$datekey]>=$today&&$g[$datekey]<=$limit)$lines[]=$c['name'].' | '.$label.' de '.$g['name'].': '.$g[$datekey];}foreach($d['links'][$cid]??[] as $eid=>$l)if(!empty($l['next'])&&$l['next']<=$today&&!in_array($l['status'],['Rechazada','Convenio formalizado'],true))$lines[]=$c['name'].' | '.collaboration_label($d,$cid,(string)$eid).' | '.$l['next'].' | '.$l['status'];foreach($d['links'][$cid]??[] as $eid=>$l)if($l['confirmed']>0&&$l['status']!=='Convenio formalizado')$lines[]=$c['name'].' | Revisar formalización: '.collaboration_label($d,$cid,(string)$eid);foreach($d['registrations']??[] as $reg)if($reg['course']===$cid&&$reg['verified'])$lines[]=$c['name'].' | Registro pendiente: '.$reg['name'];foreach($d['interest_requests']??[] as $req)if($req['course']===$cid&&!empty($req['verified_at']))$lines[]=$c['name'].' | Interés verificado pendiente: '.$req['name'];}if(!$lines)$w['digest_day']=$today;else{ $w['digest_day']=$today;save_db($dir,$d);$ok=resend_mail($cfg,$dir,$cfg['admin_email'],'FP Dual · Recordatorios '.$today,implode("\n",array_slice($lines,0,300))."\n\nConsulte el panel: ".rtrim($cfg['public_url'],'/').'/index.php?v=agenda','digest-'.hash('sha256',$today.$cfg['admin_email']));$w['digest_result']=$ok?'Aceptado por Resend':'Error o resultado incierto; consulte la agenda';}save_db($dir,$d);}
 if(!$s['enabled']||empty($d['settings']['public']))return;
 foreach($d['campaigns'] as $id=>&$p){$cid=$p['course'];if($p['state']!=='active'||($d['courses'][$cid]['closed']??true))continue;foreach($p['rows'] as $eid=>&$r){if($w['count'] >= $s['daily_limit'])break 2;$follow=$r['state']==='sent'&&$r['follow_state']==='pending';$key=$follow?'follow_state':'state';$due=$follow?$r['follow_due']:$r['due'];if($r[$key]!=='pending'||$due>$now)continue;$l=$d['links'][$cid][$eid]??null;$m=$r['email'];if($follow&&ib_hold($d,$m,(string)$eid))continue;if(!$l||!camp_status_ok($l)||!camp_allowed($d,$eid,$m)||($follow&&count($l['history'])!==($r['history_count']??-1))){$r[$key]='skipped';save_db($dir,$d);continue;}
 // Persistir antes del envío: una interrupción nunca dispara un segundo envío automático.
 $r[$key]='uncertain';$r['attempts']++;$w['count']++;$token=camp_opt_token($d,$m);save_db($dir,$d);
 $vars=camp_tokens($d,$cfg,$cid,$eid,$m);$body=strtr($follow?$p['follow_body']:$p['body'],$vars);$subject=($follow?'Seguimiento: ':'').strtr($p['subject'],$vars);$url=rtrim($cfg['public_url'],'/').'/index.php?v=unsubscribe&m='.rawurlencode($m).'&t='.$token;$body.="\n\nPara dejar de recibir estas comunicaciones: ".$url;
 $campaignCfg=$cfg;$ic=ib_config($d);if($ic['enabled'])$campaignCfg['resend_reply_to']=$ic['address'];$ok=resend_mail($campaignCfg,$dir,$m,$subject,$body,'campaign-'.hash('sha256',$id.$eid.$key));$r[$key]=$ok?'sent':'uncertain';$r['last_at']=date(DATE_ATOM);if($ok){$l['history'][]=['at'=>date(DATE_ATOM),'type'=>'Correo','note'=>($follow?'Seguimiento':'Campaña').' aceptado por Resend: '.$p['name']];if($l['status']==='Identificada')$l['status']='Contactada';$l['next']=date('Y-m-d',strtotime('+'.$p['follow_days'].' days'));$d['links'][$cid][$eid]=$l;if(!$follow&&$p['follow']){$r['follow_state']='pending';$r['follow_due']=strtotime('+'.$p['follow_days'].' days');$r['history_count']=count($l['history']);}}save_db($dir,$d);return; // un mensaje por ejecución del temporizador
 }unset($r);if(!array_filter($p['rows'],fn($r)=>$r['state']==='pending'||$r['follow_state']==='pending')){$p['state']='completed';save_db($dir,$d);}}unset($p);
}
function camp_permission_ui(array $d,string $cid,string $eid):void {echo '<h3>Autorizaciones de campañas</h3><p>No es obligatorio autorizar empresas para incorporarlas al directorio. El formulario público verificado registra automáticamente el permiso opcional. Para el contacto inicial use la sección de contacto institucional.</p>';foreach(camp_emails($d['companies'][master_id($eid)]) as $m){$p=$d['campaign_permissions'][master_id($eid)][$m]??[];form_start('camp_permission',['c'=>$cid,'e'=>$eid,'email'=>$m]);echo '<strong>'.h($m).'</strong>';if(isset($d['campaign_optouts'][$m]))echo '<p>Baja global: excluido de los envíos.</p>';select_field('allowed','Permiso',['no'=>'No autorizado','yes'=>'Autorizado'],$p['allowed']??false?'yes':'no');area('evidence','Cómo y cuándo autorizó la empresa (el formulario verificado lo registra automáticamente)',$p['evidence']??'');end_form('Guardar permiso');}}
function camp_ui(array $d,array $cfg,string $cid,bool $ed):void {$s=$d['campaign_settings'];$w=$d['campaign_worker'];$mode=(string)($_GET['mode']??'');$selected=(string)($_GET['campaign']??'');$base='?v=campaigns&c='.rawurlencode($cid);echo '<div class="record-toolbar"><a class="button secondary" href="'.h($base).'">Campañas</a><a class="button secondary" href="'.h($base.'&mode=settings').'">Automatización y límites</a>';if($ed)echo '<a class="button" href="'.h($base.'&mode=new').'">+ Nueva campaña</a>';echo '</div>';if($mode==='settings'){echo '<section class="card"><h2>Automatización y límites</h2><p>Zona horaria: Canarias. El trabajador de Ubuntu ejecuta como máximo un correo de campaña por minuto. La aceptación por Resend no acredita entrega ni lectura.</p><p>Última ejecución: '.h($w['last_run']??'Sin ejecutar').' · Intentos de hoy: '.h($w['count']??0).' · Resumen: '.h($w['digest_result']??'Sin envío').'</p>';form_start('camp_settings',['c'=>$cid]);select_field('enabled','Envío automático',['no'=>'Desactivado','yes'=>'Activado'],$s['enabled']?'yes':'no');input('daily_limit','Máximo diario de intentos de campaña (1–100)',$s['daily_limit'],'number',true);input('follow_days','Días naturales hasta el seguimiento (1–30)',$s['follow_days'],'number',true);select_field('digest','Resumen diario al administrador',['no'=>'Desactivado','yes'=>'Activado'],$s['digest']?'yes':'no');input('hour','Hora local de resumen (0–23)',$s['hour'],'number',true);input('deadline_days','Antelación de avisos de inicio y fin FEOE (0–30 días)',$s['deadline_days'],'number',true);end_form('Guardar automatización');form_start('camp_suppress',['c'=>$cid]);input('email','Correo para baja global','','email',true);end_form('Excluir correo de todas las campañas');echo '</section>';return;}
 if($mode==='new'&&$ed){$zones=[''=>'Todas'];foreach($d['links'][$cid]??[] as $eid=>$l){$z=$d['companies'][master_id($eid)]['zone'];if($z!=='')$zones[$z]=$z;}echo '<section class="card"><h2>Nueva campaña de captación</h2><p>Solo se seleccionan colaboraciones sin plazas confirmadas en estado identificada, contactada o sin respuesta. En campañas sin filtro de grupo se selecciona una sola colaboración elegible por empresa; filtre por grupo para una captación específica. Sin autorización: tarea de contacto manual, nunca envío. Revise el borrador antes de activar.</p>';form_start('camp_create',['c'=>$cid]);input('name','Nombre','Captación '.$d['courses'][$cid]['name'],'text',true);select_field('zone','Localidad',$zones);select_field('kind','Tipo de entidad',[''=>'Todos','Empresa'=>'Empresa','Organismo'=>'Organismo','Asociación'=>'Asociación']);select_field('group','Grupo',[''=>'Todos']+groups($d['courses'][$cid]));input('subject','Asunto','Colaboración FP Dual · {centro} · {curso}','text',true);area('body','Mensaje inicial',camp_default());select_field('follow','Seguimiento automático máximo uno',['no'=>'No','yes'=>'Sí']);area('follow_body','Mensaje de seguimiento',camp_default(true));echo '<p>Variables: {empresa}, {centro}, {curso}, {grupo}, {tutor}, {landing}, {ayudas}. El enlace de baja se añade automáticamente.</p>';end_form('Crear borrador');echo '</section>';return;}
 echo '<section class="card"><h2>Campañas del curso</h2>';foreach($d['campaigns'] as $id=>$p){if($p['course']!==$cid)continue;$counts=array_count_values(array_column($p['rows'],'state'));if($selected===''){echo '<div class="record-toolbar"><strong>'.h($p['name'].' · '.$p['state'].' · '.count($p['rows']).' entidades').'</strong><a class="button secondary" href="'.h($base.'&campaign='.rawurlencode((string)$id)).'">Abrir ficha</a></div>';continue;}if((string)$id!==$selected)continue;echo '<div class="record-card"><h2>'.h($p['name'].' · '.$p['state'].' · '.count($p['rows']).' entidades').'</h2><p>'.h(json_encode($counts,JSON_UNESCAPED_UNICODE)).'</p><h3>Asunto y mensaje</h3><p>'.h($p['subject']).'</p><pre class="pre">'.h($p['body']).'</pre>';if($p['follow'])echo '<p>Seguimiento tras '.h($p['follow_days']).' días naturales, si no consta cambio de estado ni nuevo contacto.</p><pre>'.h($p['follow_body']).'</pre>';if($ed){form_start('camp_tasks',['c'=>$cid,'campaign'=>$id]);end_form('Programar llamadas/visitas pendientes para hoy');if(in_array($p['state'],['draft','paused'],true)){form_start('camp_launch',['c'=>$cid,'campaign'=>$id]);echo '<label class="check"><input type="checkbox" name="confirm" value="yes" required> He revisado el texto y los destinatarios autorizados.</label>';input('start','Inicio programado (opcional; solo nuevos envíos)','','datetime-local');end_form('Activar / reanudar');}if($p['state']==='active'){form_start('camp_pause',['c'=>$cid,'campaign'=>$id]);end_form('Pausar');}if(in_array($p['state'],['draft','active','paused'],true)){form_start('camp_cancel',['c'=>$cid,'campaign'=>$id]);end_form('Cancelar definitivamente');}}echo '<div class="scroll"><table><tr><th>Empresa</th><th>Correo autorizado</th><th>Inicial</th><th>Seguimiento</th><th>Acción</th></tr>';foreach($p['rows'] as $eid=>$r){echo '<tr><td>';a('company',isset($d['links'][$cid][$eid])?collaboration_label($d,$cid,(string)$eid):$d['companies'][master_id($eid)]['name'],$cid,$eid);echo '</td><td>'.h($r['email']?:'Contacto manual').'</td><td>'.h($r['state']).'</td><td>'.h($r['follow_state']).'</td><td>';if($ed&&($r['state']==='pending'||$r['follow_state']==='pending')){form_start('camp_skip',['c'=>$cid,'campaign'=>$id,'e'=>$eid]);end_form('Omitir');}echo '</td></tr>';}echo '</table></div></div>';}echo '</section>';}
